<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Student');$q=db()->prepare("SELECT a.id,a.title,a.deadline,a.description,s.name subject FROM assignments a JOIN subjects s ON s.id=a.subject_id JOIN student_subjects ss ON ss.subject_id=a.subject_id JOIN students st ON st.id=ss.student_id WHERE a.status='published' AND a.deleted_at IS NULL AND st.user_id=? ORDER BY a.deadline");$q->execute([actor_id()]);page_top('Assignment Hub');?><div class='card p-3 table-responsive'><table class='table'><tr><th>Assignment</th><th>Subject</th><th>Deadline</th><th>Status</th><th>Action</th></tr><?php foreach($q as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['subject'])?></td><td><?=e($r['deadline'])?></td><td><span class='badge bg-info'><?=strtotime($r['deadline'])<time()?'Closed':'Open'?></span></td><td><a class='btn btn-sm btn-primary' href='assignment_submit.php?id=<?=e($r['id'])?>'>Open</a></td></tr><?php endforeach;?></table></div><?php page_bottom(); ?>